contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // params: from address, target caddress, list of tos, list of values
    function run(address from, address caddress, address[] memory _tos, uint[] memory v) public payable {
        require(_tos.length > 0);
        // record this contract balance before calling c.transfer
        uint beforeBalance = address(this).balance;

        bool reverted;
        bool ret;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }

        // After the call, the test asserts: the call (if it returned) returned true,
        // and regardless, this contract's balance did not decrease (c.transfer should not pull Ether from this test contract).
        // General rule: if the call did not revert then it returned true; also our balance is >= beforeBalance.
        assert((reverted == false && ret == true) && address(this).balance >= beforeBalance);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // If the transfer call completes (does not revert) it must return true.
    function run(address from, address caddress, address[] memory _tos, uint[] memory v) public payable {
        require(_tos.length > 0);

        bool didRevert;
        bool returnedValue;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            didRevert = false;
            returnedValue = r;
        } catch {
            didRevert = true;
            returnedValue = false;
        }

        // General rule: if the call did not revert then its returned bool is true.
        assert(didRevert || returnedValue == true);
    }

    receive() external payable {}
}

